말: 13(2)
장로: 17, 19

4.주제 만들기: 성도를 대하는 태도에 대해

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
- 젊은 과부는 결혼해서 아이를 낳고 집을 다스리게 하라
- 믿는 여자에게 과부 친척이 있으면 자기가 도와주라
- 잘 다스리는 장로는 배나 존경할 자로 알아야 한다
- 일꾼이 삯을 받는 것은 마땅하다
- 장로에 대한 고발은 두세 증인이 없으면 받지 말라
- 범죄한 자들을 모든 사람 앞에서 꾸짖어 나머지 사람들로 두려워하게 하라
 
7.하나님 찾기(해석)

8.인간 찾기(해석)
- 신자는 친척 중에 과부가 있으면 자신이 직접 돌볼 것을 권면한다.
- 당시 여자의 지위는 매우 낮았으며, 로마 시대에는 남편의 소유물로 여겨졌기 때문에 남편이 떠난 과부는 살아갈 힘도 방법도 없었다.
- 바울은 이런 상황에 있는 과부를 신자들이 사랑으로 섬길 것을 권면하고 있는 것이다.
- 사랑이 없으면 섬김도 없다.
  
- 장로(오늘날 목사)에 대한 모함과 공격이 있을 수 있기에 두세 증인이 없으면 받지 말 것을 당부한다.
- 교회를 무너뜨리기 위해 모함하는 자들이 있을 수 있다는 것을 기억해야 한다.

- 범죄한 자는 권징해야 한다. 오늘날 교회는 정의와 사랑을 명확하게 구분하여 행할 필요가 있다. 
- 범죄한 자를 사랑으로 감싸면, 죄 짓는 것을 허용하는 교회가 되고 죄 짓는 것이 문화가 되고 말 것이다.

9.적용(나) 
- 사회적 약자를 사랑하고 그들을 섬길 줄 알아야한다.

- 교회에는 세상 사람들이 들어와 있고, 이단도 들어와 있다는 것과
- 정직한 사람도 있지만, 모함하거나 거짓을 말하는 사람도 있다는 것을 잘 기억해야 한다.
- 사람의 말을 그대로 믿지 말고, 사실 여부와 그 의도를 점검해 볼 필요가 있는 것이다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-06-10', '디모데전서', '5장 21~25절', '공의의 하나님', '[딤전5:21-25]
21 하나님과 그리스도 예수와 택하심을 받은 천사들 앞에서 내가 엄히 명하노니 너는 편견이 없이 이것들을 지켜 아무 일도 불공평하게 하지 말며
22 아무에게나 경솔히 안수하지 말고 다른 사람의 죄에 간섭하지 말며 네 자신을 지켜 정결하게 하라
23 이제부터는 물만 마시지 말고 네 위장과 자주 나는 병을 위하여는 포도주를 조금씩 쓰라
24 어떤 사람들의 죄는 밝히 드러나 먼저 심판에 나아가고 어떤 사람들의 죄는 그 뒤를 따르나니
25 이와 같이 선행도 밝히 드러나고 그렇지 아니한 것도 숨길 수 없느니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

1. 1분기도

2. 본문성경 읽기(3번)

3. 반복단어 찾기(형광펜 추천)
- 어떤 사람(24절)
- 말며(21,22,23절)

4. 주제만들기: 공의의 하나님

5. 하나님 찾기 (관찰)
- 심판하시는 예수님

6. 인간 찾기 (관찰)
- 편견 없이 불공평하게 하지 말라는 바울
- 디모데의 건강을 걱정하는 바울
- 선행과 죄는 반드시 드러날 것이라 말하는 바울

7. 하나님 찾기 (해석) 
- 하나님께서는 오래 참으시며 회개의 기회를 주시는 분이지만, 끝없이 죄를 묵인하시는 분은 아니다. 하나님의 사랑은 결코 공의를 무너뜨리지 않으며, 하나님의 공의 또한 사랑을 잃지 않는다. 하나님께서는 사람의 외모를 보지 않으시며, 지위와 환경, 배경으로 사람을 판단하지 않으신다. 세상의 기준으로 높고 낮음을 나누지 않으시며, 누구에게나 동일한 사랑과 은혜의 손길을 내미신다. 
- 죄에 대해서도 마찬가지이다. 세상을 살아가다 보면 인간의 기준으로는 도저히 이해할 수 없는 일들을 많이 보게 된다. 악한 사람이 형통하기도 하고, 정직하지 못한 사람이 성공하기도 한다. 반대로 하나님을 경외하며 살아가려는 사람들이 고난을 겪고 눈물을 흘리는 모습도 자주 보게 된다. 지금 당장 모든 것이 바로잡히지 않는 것처럼 보일 수 있다. 그러나 하나님의 시간은 인간의 시간과 다르다. 하나님께서는 마지막 날에 모든 것을 드러내시고, 완전한 공의로 심판하실 것이다.
- 심판은 우리에게도 적용된다는 사실을 잊지 말아야 한다.

8. 인간(해석):

9. 적용(나): 
- 매일 하나님을 인식하며 살아갈 수 있길 기도해야겠다.

10. 영적터치(단어/구절)
- 이와 같이 선행도 밝히 드러나고 그렇지 아니한 것도 숨길 수 없느니라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-06-11', '디모데전서', '6장 1~10절', '믿음의 삶과 자족하는 마음', '디모데전서 6장 1~10절
1   무릇 멍에 아래에 있는 종들은 자기 상전들을 범사에 마땅히 공경할 자로 알지니 이는 하나님의 이름과 교훈으로 비방을 받지 않게 하려 함이라
2   믿는 상전이 있는 자들은 그 상전을 형제라고 가볍게 여기지 말고 더 잘 섬기게 하라 이는 유익을 받는 자들이 믿는 자요 사랑을 받는 자임이라 너는 이것들을 가르치고 권하라
3   누구든지 다른 교훈을 하며 바른 말 곧 우리 주 예수 그리스도의 말씀과 경건에 관한 교훈을 따르지 아니하면
4   그는 교만하여 아무 것도 알지 못하고 변론과 언쟁을 좋아하는 자니 이로써 투기와 분쟁과 비방과 악한 생각이 나며
5   마음이 부패하여지고 진리를 잃어 버려 경건을 이익의 방도로 생각하는 자들의 다툼이 일어나느니라
6   그러나 자족하는 마음이 있으면 경건은 큰 이익이 되느니라
7   우리가 세상에 아무 것도 가지고 온 것이 없으매 또한 아무 것도 가지고 가지 못하리니
8   우리가 먹을 것과 입을 것이 있은즉 족한 줄로 알 것이니라
9   부하려 하는 자들은 시험과 올무와 여러 가지 어리석고 해로운 욕심에 떨어지나니 곧 사람으로 파멸과 멸망에 빠지게 하는 것이라
10   돈을 사랑함이 일만 악의 뿌리가 되나니 이것을 탐내는 자들은 미혹을 받아 믿음에서 떠나 많은 근심으로써 자기를 찔렀도다

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
