1:감동하는 단어나 구절 찾기(영적 터치)

2026년 06월 14일 
디모데후서 1장11절-18절

1.1분기도
2. 본문 읽기(3번)
3. 반복 단어 및 같은 의미 찾기:
부끄러워하지 아니함은/부끄러워하지 아니하고: 12절 16절
지키실 줄/지키고/지키라: 12절 13절 14절
그리스도 예수/주께서: 13절 18절

4. 주제:
아름다운 것을 지키라

5. 하나님 찾기(관찰)
신자 안에 거하시는 성령님
긍휼을 베푸시는 주님

6. 인간 찾기(관찰)
복음을 위하여 세우심을 받은 바울
복음을 위하여 사슬에 매인 것을 부끄러워하지 않는 바울

7. 하나님 찾기(해석)

8.인간 찾기(해석)
사도 바울이 기록한 서신서는 모두 13권이다. 그중 디모데후서는 바울이 기록한 마지막 서신으로 알려져 있다. 

바울은 순교를 앞둔 시점에서 이 편지를 기록하였다. 잠시 자유를 얻은 때도 있었지만, 그의 노년 대부분은 쇠사슬에 묶인 채 감옥에서 보내야 했다.

그런데 이러한 상황 속에서도 바울은 사랑하는 영적 아들 디모데에게 "네게 부탁한 아름다운 것을 지키라"(딤후 1:14)고 권면한다. 

이 말씀을 묵상하며 깨닫게 되는 것은 바울의 몸은 세상의 권력자들에 의해 갇혀 있었지만, 그의 영혼은 결코 갇혀 있지 않았다는 사실이다. 

오히려 그의 마음은 성령의 은혜와 평강으로 가득 차 있었기에 절망이 아닌 아름다움을 말하고 있다.

바울이 이러한 믿음의 능력을 가질 수 있었던 이유는 12절의 고백 속에서 발견할 수 있다. “

내가 믿는 자를 내가 알고 또한 내가 의탁한 것을 그 날까지 그가 능히 지키실 줄을 확신함이라." 

바울은 단순히 하나님에 대한 지식을 가진 사람이 아니라, 자신이 믿는 주님을 인격적으로 알고 있었으며 그분을 전적으로 신뢰하고 있었다. 그래서 감옥도, 쇠사슬도, 죽음의 위협도 그의 믿음을 흔들 수 없었다.

아마 이것이 참된 믿음의 모습이 아닐까 생각한다. 믿음을 가진 사람은 세상에서 부끄러운 일이나 어려운 일을 만나더라도 쉽게 낙심하지 않는다. 

왜냐하면 자신의 삶을 지키시는 분이 하나님이심을 알기 때문이다. 그래서 믿음의 사람은 환경에 지배당하지 않고, 어떤 상황 속에서도 당당하고 의연하게 살아간다.

오늘 나 역시 바울의 고백을 본받기 원한다. 눈에 보이는 현실보다 나를 붙드시고 끝까지 지켜주실 주님을 더욱 신뢰하며, 내게 맡겨진 아름다운 복음과 사명을 끝까지 지켜가는 믿음의 사람이 되기를 기도한다.

9. 적용 (구체적으로) 
굳센 믿음 받기를 위하여 오늘 간절히 기도해야겠다. 

10. 영적 터치 (단어/구절)
14절: 우리 안에 거하시는 성령으로 말미암아 네게 부탁한 아름다운 것을 지키라

11. 믿음과 회개 및 감사 기도로 마무리하기


12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-06-16', '디모데후서', '2장 11~20절', '인정받는 일꾼으로 하나님께 드리라', '디모데후서 2장 11~20절
11   미쁘다 이 말이여 우리가 주와 함께 죽었으면 또한 함께 살 것이요
12   참으면 또한 함께 왕 노릇 할 것이요 우리가 주를 부인하면 주도 우리를 부인하실 것이라
13   우리는 미쁨이 없을지라도 주는 항상 미쁘시니 자기를 부인하실 수 없으시리라
14   너는 그들로 이 일을 기억하게 하여 말다툼을 하지 말라고 하나님 앞에서 엄히 명하라 이는 유익이 하나도 없고 도리어 듣는 자들을 망하게 함이라
15   너는 진리의 말씀을 옳게 분별하며 부끄러울 것이 없는 일꾼으로 인정된 자로 자신을 하나님 앞에 드리기를 힘쓰라
16   망령되고 헛된 말을 버리라 그들은 경건하지 아니함에 점점 나아가나니
17   그들의 말은 악성 종양이 퍼져나감과 같은데 그 중에 후메내오와 빌레도가 있느니라
18   진리에 관하여는 그들이 그릇되었도다 부활이 이미 지나갔다 함으로 어떤 사람들의 믿음을 무너뜨리느니라
19   그러나 하나님의 견고한 터는 섰으니 인침이 있어 일렀으되 주께서 자기 백성을 아신다 하며 또 주의 이름을 부르는 자마다 불의에서 떠날지어다 하였느니라
20   큰 집에는 금 그릇과 은 그릇뿐 아니라 나무 그릇과 질그릇도 있어 귀하게 쓰는 것도 있고 천하게 쓰는 것도 있나니

