디모데후서 4장 11절-22절
1.1분기도
2. 본문 읽기(3번)

3. 반복 단어 및 같은 의미 찾기:
건짐을 받았느니라/건져내시고: 17절 18절
데리고 오라/가지고 오라: 11절 12절
주께서: 14절 17절 18절 22절
문안하라/문안하느니라: 19절 21절  

4. 주제:
모든 악한 일에서 건져내신 예수

5. 하나님 찾기(관찰)
구원자 예수
힘을 주시는 예수

6. 인간 찾기(관찰)
마가를 부르는 바울
디모데에게 겉옷과 책을 가져오라고 부탁하는 바울
마무리 기도하는 바울

7. 하나님 찾기(해석)

8.인간 찾기(해석)
바울은 순교를 앞두고 마지막 서신인 디모데후서를 마무리하면서 하나님에 대한 확신의 믿음과 동시에 인간적인 모습을 함께 보여 준다. 

특별히 내 눈에 들어온 말씀은 18절이다.

“주께서 나를 모든 악한 일에서 건져내시고 또 그의 천국에 들어가도록 구원하시리니.”

여기서 “모든 악한 일에서 건져내시고”라는 말씀의 의미는 무엇일까? 

주님을 만나기 전 바울 자신의 죄악된 모습을 가리키는 것일 수도 있고, 14절에 등장하는 알렉산더와 같이 자신을 대적하고 괴롭혔던 악한 사람들과 상황을 의미하는 것일 수도 있다. 

정확히 무엇을 가리키는지 단정하기는 어렵지만, 분명한 것은 죽음을 앞둔 바울이 은혜의 사람, 용서의 사람으로 변화되어 있다는 사실이다.

16절에서 바울은 자신을 버리고 떠난 사람들에 대하여 “그들에게 허물을 돌리지 않기를 원하노라”고 말한다. 

또한 11절에서 “마가를 데리고 오라. 그가 나의 일에 유익하니라”고 기록한 것을 보면 더욱 분명해진다. 

바울은 1차 전도여행 때 중도에 떠났던 요한 마가를 인해 크게 실망하고 책망했지만, 세월이 흐른 후 영적으로 성장한 마가를 인정하며 다시 동역자로 받아들이고 있다.

이 말씀을 묵상하면서 바울은 자신을 포함한 모든 사람이 주님을 만나기 전에는 죄 가운데 있었고 악에 속한 존재였지만, 예수 그리스도를 믿음으로 구원받아 천국의 소망을 얻게 되었다는 사실을 강조하며 서신을 마무리하고 있는 것처럼 느껴진다. 

그래서 마지막 순간까지도 사람에 대한 원망보다 하나님의 은혜와 구원의 확신을 붙들고 있었던 것이다. 

나 역시 사랑하는 남북청년연합선교회 가족들과 함께 서로 사랑하며 주님을 의지하기를 원한다. 

바울이 누렸던 구원의 기쁨과 천국의 소망을 우리도 끝까지 간직하며, 어떠한 상황 속에서도 믿음을 지키며 살아가기를 소망한다.


9. 적용 (구체적으로) 
마음속에 미워하는 사람이 있는지 점검하는 시간을 가져야겠다. 

혹시 있다면 그들을 주님의 이름으로 축북하고  마가처럼 귀한 일꾼이 될 수 있도록 구해야겠다.

10. 영적 터치 (단어/구절)
18. 주께서 나를 모든 악한 일에서 건져내시고 또 그의 천국에 들어가도록 구원하시리니

11. 믿음과 회개 및 감사 기도로 마무리하기

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-06-21', '디모데후서', '4장 1~10절', '제목 없음', '(디모데후서 4장)
1. 하나님 앞과 살아 있는 자와 죽은 자를 심판하실 그리스도 예수 앞에서 그가 나타나실 것과 그의 나라를 두고 엄히 명하노니
2. 너는 말씀을 전파하라 때를 얻든지 못 얻든지 항상 힘쓰라 범사에 오래 참음과 가르침으로 경책하며 경계하며 권하라
3. 때가 이르리니 사람이 바른 교훈을 받지 아니하며 귀가 가려워서 자기의 사욕을 따를 스승을 많이 두고
4. 또 그 귀를 진리에서 돌이켜 허탄한 이야기를 따르리라
5. 그러나 너는 모든 일에 신중하여 고난을 받으며 전도자의 일을 하며 네 직무를 다하라
6. 전제와 같이 내가 벌써 부어지고 나의 떠날 시각이 가까웠도다
7. 나는 선한 싸움을 싸우고 나의 달려갈 길을 마치고 믿음을 지켰으니
8. 이제 후로는 나를 위하여 의의 면류관이 예비되었으므로 주 곧 의로우신 재판장이 그 날에 내게 주실 것이며 내게만 아니라 주의 나타나심을 사모하는 모든 자에게도니라
9. 너는 어서 속히 내게로 오라
10. 데마는 이 세상을 사랑하여 나를 버리고 데살로니가로 갔고 그레스게는 갈라디아로, 디도는 달마디아로 갔고

