예수님은 존귀하신 대제사장이시다. 우리를 구원하기 위해 자신의 영광을 취하지 않으시고, 오히려 십자가에서 죽기까지 순종하심으로 영원한 구원의 근원이 되셨다. 

또한 멜기세덱의 반차를 따른 참된 대제사장으로서 하나님께는 온전히 순종하시고, 죄인인 우리에게는 구원의 길을 열어 주셨다.

예수님의 완전한 희생으로 말미암아 이제는 구약의 제사처럼 반복해서 속죄 제물을 드리는 절차를 거치지 않게 되었다. 

예수 그리스도를 믿는 믿음으로 누구나 언제 어디서든 하나님께 나아갈 수 있는 은혜를 누리게 되었다. 

또한 시간과 장소의 제약 없이 모든 사람에게 복음을 전할 수 있는 은혜의 시대를 살아가게 되었다.

이처럼 크신 하나님의 은혜를 생각할 때마다 더욱 순종과 믿음으로 살아가야겠다는 마음을 갖게 된다. 

맡겨진 자리에서 복음 전파의 사명을 충성스럽게 감당하며, 삶으로 예수 그리스도를 증거하는 제자가 되어야겠다는 다짐을 하게 된다.

