히브리서의 저자는 예수님의 헌신과 희생의 결과인 십자가의 보혈만이 죄인을 온전하게 하고 거룩하게 할 수 있다고 선포한다. 

반면 구약의 제사는 장차 이루어질 참된 구원의 그림자일 뿐이며, 죄를 근본적으로 없애지는 못했다.

예수님께서는 죄 가운데 소망 없이 살아갈 수밖에 없는 인류를 구원하시기 위해 하나님 아버지께 끝까지 순종하셨다. 

그분은 십자가의 고통과 수치 앞에서 조금도 물러서지 않으시고 단번에 자신을 내어주셨다. 인간적인 시각으로 본다면 사형 선고를 받은 사람이 기쁜 마음으로 형장으로 걸어가는 것과 같은 모습일 것이다. 

그만큼 주님은 우리를 사랑하셨고, 자신의 고통과 수치는 중요하게 여기지 않으셨다. 영혼을 자신의 생명보다 귀하게 여기신 주님의 사랑은 참으로 측량할 수 없다.
반면 오늘날 교회 안에서도 자신의 자존심이 상하거나 무례한 대우를 받으면 용서와 화해보다 자신의 정당함을 증명하고 상대에게 되갚아 주려는 마음이 생기는 모습을 종종 본다. 참으로 안타까운 일이다. 

물론 우리는 다른 사람에게 상처를 주어서는 안 된다. 그러나 그럼에도 기독교의 본질은 용서와 화해, 그리고 사랑으로 하나 되는 데 있음을 다시 생각하게 된다.

무엇보다 이러한 말씀은 다른 사람보다 먼저 나 자신을 돌아보게 한다. 

나 역시 상처를 받으면 쉽게 용서하지 못하고, 인정받고 싶은 마음과 억울함을 내려놓지 못할 때가 많다. 

내 힘으로는 이것을 이길 수 없음을 인정한다. 그러나 주님 안에 거할 때, 그리고 십자가의 보혈의 능력을 의지할 때 비로소 용서할 수 있고 온전한 사랑으로 살아갈 수 있음을 믿는다.

기도
주님, 밖에는 많은 비가 내리고 있습니다. 그 비를 바라보며 제 마음도 주님 앞에 내려놓습니다. 제 안에는 아직도 사람들에게 인정받고 싶은 욕망이 남아 있음을 발견합니다. 황소와 염소의 피로는 결코 해결할 수 없는 이 죄를 오직 예수 그리스도의 보혈로 깨끗하게 씻어 주옵소서. 제 마음을 새롭게 하시고, 겸손과 사랑의 길을 걷게 하옵소서. 사람의 인정이 아니라 하나님의 인정만으로 만족하는 삶을 살게 하시고, 주님 안에서 참된 평강을 누리게 하옵소서.
예수 그리스도의 이름으로 기도드립니다. 아멘.

8.인간 찾기(해석)

9. 적용 (구체적으로) 
주님의 크신 사랑에 대한 관련 성경 구절을 찾아서 묵상하는 시간을 가져야겠다.

10. 영적 터치 (단어/구절):
10절: 이 뜻을 따라 예수 그리스도의 몸을 단번에 드리심으로 말미암아 우리가 거룩함을 얻었노라

11. 믿음과 회개 및 감사 기도로 마무리하기
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

