7. 하나님 찾기 (해석) 
- 감탄밖에 나오지 않는 하나님의 사랑이다. 죄로 인해 하나님께 나아갈 수 없던 인간을 위해 하나님께서는 친히 이 땅에 내려오셨다. 그리고 십자가에서 피 흘리심으로 하나님께 나아갈 수 있는 길을 열어 주셨다. 인간이 하나님께 올라갈 수 없었기에, 하나님께서 인간에게 내려오신 것이다. 이것이 복음이며, 하나님의 사랑이다
- 문득 이런 생각을 해본다. 만약 하나님께서 이 땅에 오시지 않으셨다면, 그리고 지금도 구약의 제사 제도만 남아 있었다면 인간은 하나님을 어떻게 생각했을까. 하나님을 더 두려워했을까, 아니면 지금처럼 멀리했을까. 그 답은 알 수 없지만 분명한 것은 하나님께서는 우리와의 거리를 그대로 두지 않으셨다는 사실이다. 하나님은 우리에게 먼저 다가오셨다.
- 그런데 인간은 참으로 연약하다. 하나님의 은혜가 계속될수록 그것을 당연하게 여기고, 때로는 믿기 어렵다고 말하기도 한다. 나 또한 다르지 않다. 말씀과 기도에서 멀어질수록 하나님의 사랑보다 삶의 염려가 더 크게 보이고, 영원한 소망보다 세상의 욕심이 마음을 채우는 모습을 발견한다.
- 어리석은 것에 나의 시선이 머물지 않고 하나님의 은혜에 사로잡혀 살아가기를 소망한다. 하나님께서 베푸신 사랑이 내 안에 차고 넘쳐 더 이상 담아둘 수 없을 만큼 흘러넘치기를 기도한다.

