- 히브리서 기자는 고난 가운데 있는 신자에게 하나님을 떠나지 말고 고난을 이겨내라 격려하고 있다
- 과거 빛을 처음 받았을 때 비방과 환난을 당하거나 이런 형편에 있는 자들과 사귀며 돌 본 것을 말하여 기억하게 하고 있다
- 또한 자기 소유가 빼앗기는 일이 있어도 기쁘게 받아들인 것을 말하며, 그렇게 한 것은 더 좋고 영구한 소유가 있는 줄 알았기 떄문이었음을 언급한다.

- 현재 고난이 극심하지만 담대함을 버리자 말라고 응원한다.
- 잠시 잠깐 후면 예수님이 오실 것이며 지체하지 않을 것이다라고 말하며 위로한다.
