- 생로병사와 통과의례, 갑작스러운 사고에 의한 슬픔만 있을 뿐이다.
- 믿음의 선진들이 고난과 싸워 지켜낸 믿음이 우리에게 잘 전달되었다.
- 이것을 기억하고 주님께 감사하며, 믿음의 선진들이 고난을 이겨내고 복음을 전했기에 오늘날 내가 있음을 기억해야 한다. 

