5. 하나님 찾기 (관찰)

6. 인간 찾기 (관찰)
- 믿음으로 죽은 후에도 하나님의 약속이 이루어질 것을 믿은 요셉
- 믿음으로 왕자 칭함을 거부하고 고난을 택한 모세 

7. 하나님 찾기 (해석) 

8. 인간(해석):
- 오늘 히브리서를 묵상하며 두 사람의 믿음이 마음에 깊이 남았다.
- 첫 번째는 요셉의 믿음이다. 우리는 말씀과 예배, 기도를 통해 하나님의 약속을 붙들지만, 시간이 흐를수록 믿음은 쉽게 흔들린다. 대부분은 살아 있는 동안 응답받기를 원하기 때문이다. 그러나 요셉은 달랐다. 그는 하나님께서 약속하신 가나안 땅에 들어가지 못한 채 애굽에서 죽음을 맞이했지만, 자신의 뼈를 반드시 그 땅으로 옮겨 달라고 유언했다. 죽음 이후에도 하나님의 약속은 반드시 이루어진다는 사실을 믿었기 때문이다. 그의 믿음은 후손들에게 소망이 되었고, 결국 400여 년 후 그의 뼈는 가나안 땅에 안장되었다. 하나님의 약속은 사람의 생애보다 크고, 하나님의 시간 속에서 반드시 이루어진다는 사실을 보여 준다.
- 두 번째는 모세의 믿음이다. 모세는 애굽의 부귀와 영화를 뒤로하고 하나님의 백성과 함께 고난받는 길을 선택했다. 말은 쉽지만 실제로 그런 선택을 하기는 어렵다. 그러나 모세는 잠시 누리는 죄악의 즐거움보다 하나님과 함께하는 고난이 더 귀하다는 것을 알았다. 그래서 출애굽의 과정과 광야에서의 수많은 어려움도 믿음으로 감당할 수 있었다.
- 오늘 나는 어떤 믿음으로 살아가고 있는지 돌아본다. 현실의 어려움 때문에 눈앞의 문제만 바라볼 때가 많지만, 하나님께서는 영원한 소망을 바라보는 믿음을 원하신다. 잠시 스쳐 지나갈 세상의 즐거움보다 하나님께서 약속하신 나라를 더욱 사모하며, 끝까지 믿음을 붙드는 삶을 살아가기를 기도한다.

9. 적용(나): 
- 믿음으로 소망을 품고 살아가길 기도해야겠다.

10. 영적터치(단어/구절)
- 믿음으로

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2026-07-25', '히브리서', '11장 31~40절', '제목 없음', '홈페이지를 ''남북청년연합선교회''로 이전합니다.

검색 창에서 ''남북청년연합선교회'' 로 검색해 주세요. 

 

(히브리서 11장)
31. 믿음으로 기생 라합은 정탐꾼을 평안히 영접하였으므로 순종하지 아니한 자와 함께 멸망하지 아니하였도다
32. 내가 무슨 말을 더 하리요 기드온, 바락, 삼손, 입다, 다윗 및 사무엘과 선지자들의 일을 말하려면 내게 시간이 부족하리로다
33. 그들은 믿음으로 나라들을 이기기도 하며 의를 행하기도 하며 약속을 받기도 하며 사자들의 입을 막기도 하며
34. 불의 세력을 멸하기도 하며 칼날을 피하기도 하며 연약한 가운데서 강하게 되기도 하며 전쟁에 용감하게 되어 이방 사람들의 진을 물리치기도 하며
35. 여자들은 자기의 죽은 자들을 부활로 받아들이기도 하며 또 어떤 이들은 더 좋은 부활을 얻고자 하여 심한 고문을 받되 구차히 풀려나기를 원하지 아니하였으며
36. 또 어떤 이들은 조롱과 채찍질뿐 아니라 결박과 옥에 갇히는 시련도 받았으며
37. 돌로 치는 것과 톱으로 켜는 것과 시험과 칼로 죽임을 당하고 양과 염소의 가죽을 입고 유리하여 궁핍과 환난과 학대를 받았으니
38. (이런 사람은 세상이 감당하지 못하느니라) 그들이 광야와 산과 동굴과 토굴에 유리하였느니라
39. 이 사람들은 다 믿음으로 말미암아 증거를 받았으나 약속된 것을 받지 못하였으니
40. 이는 하나님이 우리를 위하여 더 좋은 것을 예비하셨은즉 우리가 아니면 그들로 온전함을 이루지 못하게 하려 하심이라

